interface.definition:
#"SYSTEM_SYSRULES_cardLayout"(
  contents: {
    #"SYSTEM_SYSRULES_columnsLayout"(
      columns: {
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            #"SYSTEM_SYSRULES_richTextDisplayField"(
              labelPosition: "COLLAPSED",
              value: {
                #"SYSTEM_SYSRULES_richTextItem_v1"(
                  text: "Filters",
                  color: "STANDARD",
                  size: "MEDIUM",
                  style: "STRONG"
                )
              }
            )
          }
        )
      }
    ),
    #"SYSTEM_SYSRULES_columnsLayout"(
      columns: {
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            #"SYSTEM_SYSRULES_multipleDropdownField_v1"(
              label: "Fiscal Year",
              placeholder: "Fiscal Year",
              choiceLabels: ri!fYearDropdown,
              choiceValues: ri!fYearDropdown,
              value: ri!yearFilter,
              saveInto: {
                ri!yearFilter,
                a!save(
                  ri!documentId,
                  null
                )
              }
            )
          }
        ),
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            #"SYSTEM_SYSRULES_pickerFieldCustom"(
              label: "Candidate Name",
              placeholder: "Enter at least " & #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3895397" & " characters to search for a candidate",
              suggestFunction: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6761001"(filter: _),
              selectedLabels: ri!nameFilter,
              value: ri!nameFilter,
              saveInto: {
                ri!nameFilter,
                a!save(
                  ri!documentId,
                  null
                )
              }
            )
          }
        )
      }
    )
  },
  style: "ACCENT",
  marginBelow: "STANDARD"
)
